static void pump(DWORD ms){ULONGLONG end=GetTickCount64()+ms;MSG m;do{while(PeekMessageW(&m,NULL,0,0,PM_REMOVE)){TranslateMessage(&m);DispatchMessageW(&m);++dispatched;}Sleep(5);}while(GetTickCount64()<end);}
