static void mouse(int x,int y,DWORD flags,LONG data)
{DWORD pid=0;INPUT i={0};if(flags&(MOUSEEVENTF_LEFTDOWN|MOUSEEVENTF_WHEEL)){GetWindowThreadProcessId(WindowFromPoint((POINT){x,y}),&pid);if(pid!=GetCurrentProcessId()){check(0,"real mouse target belongs to display probe");return;}}i.type=INPUT_MOUSE;i.mi.dx=MulDiv(x-GetSystemMetrics(SM_XVIRTUALSCREEN),65535,GetSystemMetrics(SM_CXVIRTUALSCREEN)-1);i.mi.dy=MulDiv(y-GetSystemMetrics(SM_YVIRTUALSCREEN),65535,GetSystemMetrics(SM_CYVIRTUALSCREEN)-1);i.mi.dwFlags=MOUSEEVENTF_ABSOLUTE|MOUSEEVENTF_VIRTUALDESK|MOUSEEVENTF_MOVE|flags;i.mi.mouseData=(DWORD)data;check(SendInput(1,&i,sizeof(i))==1,"SendInput mouse");pump(60);}
static void key(WORD k,int control)
{DWORD pid=0,extended=k>=VK_PRIOR&&k<=VK_DOWN?KEYEVENTF_EXTENDEDKEY:0;INPUT a[4]={0};int n=0;GetWindowThreadProcessId(GetForegroundWindow(),&pid);if(pid!=GetCurrentProcessId()){check(0,"real keyboard foreground belongs to this probe");return;}if(control){a[n].type=INPUT_KEYBOARD;a[n++].ki.wVk=VK_CONTROL;}a[n].type=INPUT_KEYBOARD;a[n].ki.wVk=k;a[n++].ki.dwFlags=extended;a[n].type=INPUT_KEYBOARD;a[n].ki.wVk=k;a[n++].ki.dwFlags=extended|KEYEVENTF_KEYUP;if(control){a[n].type=INPUT_KEYBOARD;a[n].ki.wVk=VK_CONTROL;a[n++].ki.dwFlags=KEYEVENTF_KEYUP;}for(int i=0;i<n;++i){a[i].ki.wScan=(WORD)MapVirtualKeyW(a[i].ki.wVk,MAPVK_VK_TO_VSC);a[i].ki.wVk=0;a[i].ki.dwFlags|=KEYEVENTF_SCANCODE;}if(control){check(SendInput(1,a,sizeof(INPUT))==1,"SendInput modifier down");pump(0);check(SendInput(n-2,a+1,sizeof(INPUT))==(UINT)(n-2),"SendInput navigation with modifier");pump(0);check(SendInput(1,a+n-1,sizeof(INPUT))==1,"SendInput modifier up");pump(0);}else check(SendInput(n,a,sizeof(INPUT))==(UINT)n,"SendInput keyboard");pump(80);printf("KEY vk=%u control=%d async-control=%d queue-control=%d dispatched=%llu\n",k,control,(GetAsyncKeyState(VK_CONTROL)&0x8000)!=0,(GetKeyState(VK_CONTROL)&0x8000)!=0,dispatched);check(!(GetAsyncKeyState(VK_CONTROL)&0x8000),"real keyboard modifier released");}
static void clipboard_seed(const wchar_t *text)
{size_t bytes=(wcslen(text)+1)*sizeof(wchar_t);HGLOBAL data=GlobalAlloc(GMEM_MOVEABLE,bytes);void *memory=data?GlobalLock(data):NULL;check(memory!=NULL,"clipboard allocation");if(!memory)return;memcpy(memory,text,bytes);GlobalUnlock(data);if(!OpenClipboard(root)){GlobalFree(data);check(0,"clipboard open");return;}check(EmptyClipboard(),"clipboard empty");if(!SetClipboardData(CF_UNICODETEXT,data)){GlobalFree(data);check(0,"clipboard set");}CloseClipboard();}
static void frame(const char *name)
{int x=GetSystemMetrics(SM_XVIRTUALSCREEN),y=GetSystemMetrics(SM_YVIRTUALSCREEN),w=GetSystemMetrics(SM_CXVIRTUALSCREEN),h=GetSystemMetrics(SM_CYVIRTUALSCREEN);HDC screen=GetDC(NULL),dc=CreateCompatibleDC(screen);BITMAPINFO info={0};BITMAPFILEHEADER header={0};void *pixels;HBITMAP bitmap;HGDIOBJ old;FILE *f;char path[1024];POINT at;DWORD pid=0;HWND hit;wchar_t cls[128];
 info.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);info.bmiHeader.biWidth=w;info.bmiHeader.biHeight=-h;info.bmiHeader.biPlanes=1;info.bmiHeader.biBitCount=32;info.bmiHeader.biCompression=BI_RGB;bitmap=CreateDIBSection(screen,&info,DIB_RGB_COLORS,&pixels,NULL,0);old=SelectObject(dc,bitmap);check(BitBlt(dc,0,0,w,h,screen,x,y,SRCCOPY|CAPTUREBLT),"desktop capture");header.bfType=0x4d42;header.bfOffBits=sizeof(header)+sizeof(info.bmiHeader);header.bfSize=header.bfOffBits+w*h*4;snprintf(path,sizeof(path),"%s/%03d-%s.bmp",directory,sequence++,name);f=fopen(path,"wb");if(f){fwrite(&header,1,sizeof(header),f);fwrite(&info.bmiHeader,1,sizeof(info.bmiHeader),f);fwrite(pixels,1,w*h*4,f);fclose(f);}else check(0,"write frame");GetCursorPos(&at);hit=WindowFromPoint(at);GetClassNameW(hit,cls,128);GetWindowThreadProcessId(hit,&pid);printf("FRAME tick=%llu dispatched=%llu name=%s button=%d capture=%p hit=%p class=%ls pid=%lu xy=%ld,%ld focus=%p\n",GetTickCount64(),dispatched,name,(GetAsyncKeyState(VK_LBUTTON)&0x8000)!=0,(void *)GetCapture(),(void *)hit,cls,pid,at.x,at.y,(void *)GetFocus());SelectObject(dc,old);DeleteObject(bitmap);DeleteDC(dc);ReleaseDC(NULL,screen);}

static ui_status_t display_present(ui_component_t *c,const char *id,ui_element_presentation_t *p)
{ui_status_t status;ULONGLONG end=GetTickCount64()+10000;do{status=ui_component_get_presentation(c,id,p);if(status!=UI_STATUS_PENDING)return status;pump(1);}while(GetTickCount64()<end);return status;}
static ui_status_t display_capture(ui_component_t *c,int width,int height,uint32_t dpi,ui_pixel_buffer_t *pixels)
{ui_status_t status;ULONGLONG end=GetTickCount64()+10000;do{status=ui_component_capture_rgba(c,width,height,dpi,pixels);if(status!=UI_STATUS_PENDING)return status;pump(1);}while(GetTickCount64()<end);return status;}
static void real_text(const wchar_t *text)
{DWORD pid=0;GetWindowThreadProcessId(GetForegroundWindow(),&pid);if(pid!=GetCurrentProcessId()){check(0,"text foreground is owned");return;}for(const wchar_t *at=text;*at;++at){INPUT i[2]={0};i[0].type=i[1].type=INPUT_KEYBOARD;i[0].ki.wScan=i[1].ki.wScan=*at;i[0].ki.dwFlags=KEYEVENTF_UNICODE;i[1].ki.dwFlags=KEYEVENTF_UNICODE|KEYEVENTF_KEYUP;check(SendInput(2,i,sizeof(INPUT))==2,"real text input");pump(80);}}
static void remember_children(void)
{DWORD ids[64]={0};size_t count=1;HANDLE snapshot;PROCESSENTRY32W entry={0};ids[0]=GetCurrentProcessId();snapshot=CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS,0);check(snapshot!=INVALID_HANDLE_VALUE,"owned child snapshot");if(snapshot==INVALID_HANDLE_VALUE)return;entry.dwSize=sizeof(entry);
 for(int pass=0;pass<64;++pass){int added=0;if(Process32FirstW(snapshot,&entry))do{int parent=0,known=0;for(size_t i=0;i<count;++i){if(ids[i]==entry.th32ParentProcessID)parent=1;if(ids[i]==entry.th32ProcessID)known=1;}if(parent&&!known){if(count==64){check(0,"owned child tracking capacity");break;}ids[count++]=entry.th32ProcessID;added=1;}}while(Process32NextW(snapshot,&entry));if(!added)break;}CloseHandle(snapshot);
 for(size_t i=1;i<count;++i){HANDLE process=OpenProcess(SYNCHRONIZE|PROCESS_QUERY_LIMITED_INFORMATION,FALSE,ids[i]);if(process){display_children[display_child_count]=process;display_child_ids[display_child_count++]=ids[i];printf("CHILD running pid=%lu\n",ids[i]);}}}
static void wait_children(void)
{ULONGLONG end=GetTickCount64()+10000;size_t pending;do{pending=0;pump(1);for(size_t i=0;i<display_child_count;++i)if(WaitForSingleObject(display_children[i],0)!=WAIT_OBJECT_0)++pending;}while(pending&&GetTickCount64()<end);check(!pending,"owned Runtime processes actually exited before return");for(size_t i=0;i<display_child_count;++i){DWORD code=STILL_ACTIVE;DWORD wait=WaitForSingleObject(display_children[i],0);GetExitCodeProcess(display_children[i],&code);printf("CHILD final pid=%lu signaled=%d exitCode=%lu\n",display_child_ids[i],wait==WAIT_OBJECT_0,code);if(wait==WAIT_OBJECT_0)check(code==0,"owned Runtime process normal exit");CloseHandle(display_children[i]);}display_child_count=0;pump(0);}
