static void rows(ui_component_t *c,const ui_component_query_t *q,void *data)
{const char *ids[]={"a","b","c","d"};ui_row_t r[2]={0};ui_cell_t v[2][4]={0};ui_component_batch_t batch={0};size_t n=q->first<2?2-(size_t)q->first:0;(void)data;if(q->kind!=UI_QUERY_ROWS)return;if(n>q->count)n=q->count;for(size_t i=0;i<n;++i){r[i].size=sizeof(r[i]);r[i].id=q->first+i+1;r[i].title="Row";r[i].cells=v[i];r[i].cell_count=q->column_count;r[i].content_version=1;for(size_t j=0;j<q->column_count;++j){v[i][j].size=sizeof(v[i][j]);v[i][j].column_id=ids[q->first_column+j];v[i][j].kind=UI_VALUE_TEXT;v[i][j].text="Cell text";}}batch.size=sizeof(batch);batch.component_generation=q->component_generation;batch.request_id=q->request_id;batch.first=q->first;batch.total_count=2;batch.rows=r;batch.row_count=n;check(ui_component_submit(c,&batch)==UI_STATUS_OK,"table rows");}
